// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { Heading } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Foundations/Heading)

figma.connect(Heading, FIGMA_NODE_URL, {
  props: {
    variant: figma.enum('variant', { 'title': 'title', 'section': 'section', 'card': 'card', 'h24': 'h24', 'h32': 'h32' }),
  },
  example: ({ variant }) => (
    <Heading variant={variant}></Heading>
  ),
});
